from math import log2

def gini(counts):
    n = sum(counts)
    if n == 0:
        return 0.0
    return round(1 - sum((c / n) ** 2 for c in counts), 6)

def entropy(counts):
    """In bits; classes with a count of 0 are skipped."""
    n = sum(counts)
    return round(-sum(c / n * log2(c / n) for c in counts if c > 0), 6)

