from collections import Counter
from math import log2

def impurity(labels, criterion="gini"):
    """Gini or entropy (bits) of a list of labels; 0.0 for an empty list."""
    n = len(labels)
    if n == 0:
        return 0.0
    ps = [c / n for c in Counter(labels).values()]
    if criterion == "gini":
        return 1 - sum(p * p for p in ps)
    return -sum(p * log2(p) for p in ps)

def split_gain(y_left, y_right, criterion="gini"):
    parent = list(y_left) + list(y_right)
    n = len(parent)
    child = (len(y_left) * impurity(y_left, criterion)
             + len(y_right) * impurity(y_right, criterion)) / n
    return round(impurity(parent, criterion) - child, 6)

