def best_split(X, y):
    """(feature, threshold, gain) with the largest Gini gain;
    (None, None, 0.0) when no split gains anything."""
    y = list(y)
    best = (None, None, 0.0)
    for f in range(len(X[0])):
        col = [row[f] for row in X]
        values = sorted(set(col))
        for a, b in zip(values, values[1:]):
            t = (a + b) / 2
            left = [lab for v, lab in zip(col, y) if v <= t]
            right = [lab for v, lab in zip(col, y) if v > t]
            g = impurity(y) - (len(left) * impurity(left)
                               + len(right) * impurity(right)) / len(y)
            if g > best[2]:
                best = (f, t, g)
    if best[0] is None:
        return best
    return (best[0], round(best[1], 6), round(best[2], 6))
